'use client'
import { useState } from 'react'
import { acceptPlanApplication } from '@/app/marketplace/actions'
export default function ApplicationsClient({incoming, sent}:{incoming:any[];sent:any[]}){const[items,setItems]=useState(incoming);const[note,setNote]=useState('');async function accept(id:string){const r=await acceptPlanApplication(id);if('error'in r)setNote(r.error);else{setItems(x=>x.map(a=>a.id===id?{...a,status:'accepted'}:a));setNote('Plan locked in.')} }return <>{note&&<p style={{color:'var(--primary)',fontSize:13}}>{note}</p>}<h2 style={{fontSize:18,margin:'28px 0 14px'}}>People who want to join your plans</h2>{items.length===0?<div className="app-card" style={{padding:24,color:'var(--muted-foreground)'}}>When someone says “I’m in”, you will see them here.</div>:<div style={{display:'grid',gap:12}}>{items.map(a=><article className="app-card" key={a.id} style={{padding:18,display:'flex',justifyContent:'space-between',gap:12}}><div><strong>{a.plans?.activity||'Your plan'}</strong><small style={{display:'block',color:'var(--muted-foreground)'}}>Offer: ₹{Number(a.proposed_rate).toLocaleString('en-IN')} · {a.status}</small><p style={{fontSize:13}}>{a.message}</p></div>{a.status==='pending'&&<button className="app-btn app-btn-primary" onClick={()=>accept(a.id)}>Accept</button>}</article>)}</div>}<h2 style={{fontSize:18,margin:'32px 0 14px'}}>Your requests</h2>{sent.length===0?<div className="app-card" style={{padding:24,color:'var(--muted-foreground)'}}>Requests you send will appear here.</div>:<div style={{display:'grid',gap:12}}>{sent.map(a=><div className="app-card" key={a.id} style={{padding:18,display:'flex',justifyContent:'space-between'}}><span>{a.plans?.activity||'Plan'}<small style={{display:'block',color:'var(--muted-foreground)'}}>{a.plans?.location}</small></span><strong>{a.status}</strong></div>)}</div>}</>}
